        TreeNode root = new TreeNode(Integer.parseInt(tokens[0]));
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < count) {
            TreeNode node = queue.poll();
            if (i < count && !tokens[i].equals("null")) {
